/* @autogenerated */
import { Observable, of } from 'rxjs';
import { Slide } from '@shared/data/repository/provider/repository-provider.interface';
import { parseCell } from '@shared/toolkit/entity-import/cell-parse';
import { readWorkbook } from '@shared/toolkit/entity-import/excel-reader';
import { buildDataBook } from '@shared/toolkit/entity-import/excel-writer';
import { ExportColumn } from './entity-export.model';
import { cellOf, collectAll, collectSelected, formatOf, referencesOf } from './export-rows';

interface Row {
  uid: string;
}

/** Listado de `total` elementos paginado con un cursor numérico en `next`. */
function pagedList(total: number) {
  const queries: any[] = [];
  const list = (query: any): Observable<Slide<Row>> => {
    queries.push(query);
    const all = Array.from({ length: total }, (_, index) => ({ uid: `u${index}` }));
    const source = query.uids ? all.filter((row) => query.uids.includes(row.uid)) : all;
    const start = Number(query.cursor ?? 0);
    const content = source.slice(start, start + query.limit);
    const hasNext = start + query.limit < source.length;
    return of({ content, hasNext, next: hasNext ? { cursor: String(start + query.limit) } : {} });
  };
  return { list, queries };
}

describe('export-rows', () => {
  it('walks every page merging next into the filter', async () => {
    const { list, queries } = pagedList(5);
    const progress: number[] = [];

    const result = await collectAll(list, { name: 'x' }, { pageSize: 2, onProgress: (read) => progress.push(read) });

    expect(result.items.map((row) => row.uid)).toEqual(['u0', 'u1', 'u2', 'u3', 'u4']);
    expect(result.truncated).toBeFalse();
    expect(queries).toEqual([
      { name: 'x', limit: 2 },
      { name: 'x', limit: 2, cursor: '2' },
      { name: 'x', limit: 2, cursor: '4' },
    ]);
    expect(progress).toEqual([2, 4, 5]);
  });

  it('stops at the limit and reports that rows were left out', async () => {
    const { list } = pagedList(10);

    const result = await collectAll(list, {}, { pageSize: 3, limit: 4 });

    expect(result.items.length).toBe(4);
    expect(result.truncated).toBeTrue();
  });

  it('stops asking when aborted', async () => {
    const { list, queries } = pagedList(10);
    const abort = new AbortController();

    const run = collectAll(list, {}, { pageSize: 2, signal: abort.signal, onProgress: () => abort.abort() });

    await expectAsync(run).toBeRejected();
    expect(queries.length).toBe(1);
  });

  it('fetches the selection by uids in chunks and keeps its order', async () => {
    const { list, queries } = pagedList(120);
    const uids = Array.from({ length: 60 }, (_, index) => `u${119 - index}`);

    const result = await collectSelected(list, uids);

    expect(result.items.map((row) => row.uid)).toEqual(uids);
    expect(queries.map((query) => query.uids.length)).toEqual([50, 10]);
  });

  it('collects each reference once', () => {
    expect(referencesOf([{ t: { $ref: 'a' } }, { t: { $ref: 'a' } }, { t: null }, { t: { $ref: 'b' } }], 't')).toEqual([
      'a',
      'b',
    ]);
  });

  describe('cells', () => {
    const columns: ExportColumn[] = [
      { field: 'name', label: 'name', text: 'Nombre' },
      { field: 'tenant', label: 'tenant', text: 'Tenant', type: 'reference' },
      { field: 'enabled', label: 'enabled', text: 'Habilitado', type: 'boolean' },
      { field: 'count', label: 'count', text: 'Total', type: 'number' },
      { field: 'blockedUntil', label: 'blocked', text: 'Bloqueado hasta', type: 'datetime' },
      {
        field: 'status',
        label: 'status',
        text: 'Situación',
        type: 'enum',
        options: [{ value: 'accepted', label: 'accepted' }],
        optionTexts: { accepted: 'Aceptado' },
      },
    ];
    const item = {
      name: 'ana',
      tenant: { $ref: 't1' },
      enabled: false,
      count: 3,
      blockedUntil: '2026-03-04T10:30:00',
      status: 'accepted',
    };

    it('writes references by name, enums by label and dates as dates', () => {
      const cells = columns.map((column) => cellOf(item, column, { t1: 'Acme' }));

      expect(cells.slice(0, 4)).toEqual(['ana', 'Acme', false, 3]);
      expect(cells[4]).toEqual(new Date('2026-03-04T10:30:00'));
      expect(cells[5]).toBe('Aceptado');
      expect(cellOf({ tenant: { $ref: 'zz' } }, columns[1], {})).toBe('zz');
      expect(cellOf({}, columns[0])).toBeNull();
    });

    it('produces a file that the import reads back to the same values', async () => {
      const XLSX = await import('xlsx');
      const book = await buildDataBook({
        name: 'Datos',
        headers: columns.map((column) => column.text),
        rows: [columns.map((column) => cellOf(item, column, { t1: 'Acme' }))],
        formats: columns.map(formatOf),
      });
      const file = new File([XLSX.write(book, { type: 'array', bookType: 'xlsx' })], 'export.xlsx');

      const [sheet] = await readWorkbook(file);
      const parsed = columns.map((column, index) =>
        parseCell(sheet.rows[0].cells[index], {
          field: column.field,
          type: column.type ?? 'text',
          label: column.text,
          index,
          options: column.options?.map((option) => ({ value: option.value, names: ['Aceptado'] })),
        }),
      );

      expect(sheet.headers).toEqual(columns.map((column) => column.text));
      expect(parsed.map((cell) => ('value' in cell ? cell.value : cell.error))).toEqual([
        'ana',
        'Acme',
        false,
        3,
        new Date('2026-03-04T10:30:00'),
        'accepted',
      ]);
    });
  });
});
